fun defaultIsPretty(sys: System?): Boolean {
    if (sys!!.getEnvironmentVariable("NO_COLOR") != "") {
        return false
    }
    if (sys!!.getEnvironmentVariable("FORCE_COLOR") != "") {
        return true
    }
    return sys!!.writeOutputIsTTY()
}

